import{_ as n,o as a,c as r,a3 as s}from"./chunks/framework.z_KJ15Ep.js";const t="/bilder/unterricht-kataloge/kataloge-fachklassen-header.png",i="/bilder/unterricht-kataloge/kataloge-fachklassen-hinzufuegen.png",l="/bilder/unterricht-kataloge/kataloge-fachklassen-details.png",d="/bilder/unterricht-kataloge/kataloge-fachklassen-editor.png",m=JSON.parse('{"title":"Fachklassen am Berufskolleg verwalten","description":"","frontmatter":{"title":"Fachklassen am Berufskolleg verwalten","source_pageid":1415,"source_revision":5649},"headers":[],"relativePath":"schild3/unterricht-kataloge/fachklassen-schulbezogene-kataloge.md","filePath":"schild3/unterricht-kataloge/fachklassen-schulbezogene-kataloge.md"}'),g={name:"schild3/unterricht-kataloge/fachklassen-schulbezogene-kataloge.md"};function h(u,e,o,c,f,k){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="fachklassen-am-berufskolleg-verwalten" tabindex="-1">Fachklassen am Berufskolleg verwalten <a class="header-anchor" href="#fachklassen-am-berufskolleg-verwalten" aria-label="Permalink to &quot;Fachklassen am Berufskolleg verwalten&quot;">​</a></h1><p>Der Fachklassenkatalog bildet die Grundlage für die Zuordnung von Fachklassen am Berufskolleg. Die Anleitung führt von der Auswahl und Anlage der Einträge zu den einzelnen Fachklassendetails.</p><h2 id="fachklassen-auswahlen-und-anlegen" tabindex="-1">Fachklassen auswählen und anlegen <a class="header-anchor" href="#fachklassen-auswahlen-und-anlegen" aria-label="Permalink to &quot;Fachklassen auswählen und anlegen&quot;">​</a></h2><p>Pflegen Sie die Fachklassen und ihre Eigenschaften, insbesondere Gliederung und Berufsangaben für den Zeugnisdruck.</p><p><a href="/bilder/unterricht-kataloge/kataloge-fachklassen-header.png"><img src="'+t+'" alt="Der Katalog mit den Fachklassen." loading="lazy"></a></p><p><em>Der Katalog mit den Fachklassen.</em></p><p>Über den Katalog <strong>Fachklassen</strong> lassen sich am BK eben diese Fachklassen anlegen und verwalten. Die Fachklassen werden in der Regel für die einzelnen Ausbildungsberufe und Ausbildungsjahre gebildet.</p><p>Die Fachklassen in folgende Fachbereiche gegliedert: Agrarwirtschaft, Ernährungs- und Versorgungsmanagement, Gestaltung, Gesundheit/Erziehung und Soziales, Informatik, Technik/Naturwissenschaften und Wirtschaft und Verwaltung.</p><p>Weiterhin kann über <strong>Sortierung</strong> die <em>benutzerdefinierte Sortierung</em> gewählt werden, dann lässt sich die Reihenfolge der Fachklassen über die Pfeile links verändern.</p><p>Der Knopf <strong>Excel-Export</strong> lässt den Katalog in eine Excel-Datei speichern.</p><p><a href="/bilder/unterricht-kataloge/kataloge-fachklassen-hinzufuegen.png"><img src="'+i+'" alt="Beim Anlegen neuer Fachklassen werden Auswahlmenüs zu Gliederung und zulässigen Fachklassen angezeigt." loading="lazy"></a></p><p><em>Beim Anlegen neuer Fachklassen werden Auswahlmenüs zu Gliederung und zulässigen Fachklassen angezeigt.</em></p><p>Die Verwaltung des Katalogs lässt über <strong>+</strong> und <strong>-</strong> das Anlegen und Löschen von Katalogeinträgen zu.</p><p><a href="/bilder/unterricht-kataloge/kataloge-fachklassen-details.png"><img src="'+l+`" alt="Zu jeder Fachklasse werden ihre Details angezeigt." loading="lazy"></a></p><p><em>Zu jeder Fachklasse werden ihre Details angezeigt.</em></p><h2 id="fachklassendetails-und-berufsangaben-pflegen" tabindex="-1">Fachklassendetails und Berufsangaben pflegen <a class="header-anchor" href="#fachklassendetails-und-berufsangaben-pflegen" aria-label="Permalink to &quot;Fachklassendetails und Berufsangaben pflegen&quot;">​</a></h2><p>Unter den Details zu jeder Fachklasse wird zuerst ihre am BK vorgesehene <strong>Gliederung</strong> angezeigt.</p><p>Die drei Felder zur <strong>Berufsebene</strong> werden beim Zeugnisdruck ausgewertet und geben <em>Fachbereich</em>, <em>Fachrichtung</em> und <em>Schwerpunkt</em> an. Hierbei ist die <strong>Berufsebene 1</strong> die <em>Fachrichtung</em> und die <strong>Berufsebene 2</strong> der <em>Schwerpunkt</em>, die Eintragungen hier werden auf die Zeugnisse übernommen.</p><p>In der bei den Reports mitgelieferten Anleitung der Zeugnisformulare sind hierfür relevante Informationen enthalten.</p><p>Weiterhin lässt sich der Katalogeintrag über den Haken auf <strong>sichtbar</strong> oder unsichtbar schalten. Ein unsichtbarer Eintrag wird in den Dropdown-Menüs zu Fachklassen nicht aufgeführt, existiert aber noch im Katalog.</p><p>Unterhalb des Hakens für <em>sichtbar</em> befindet sich der <strong>Fachklassenschlüssel</strong>, der für die Statistik ausgegeben wird.</p><p>Die beiden Einträge zur <strong>Bezeichnung</strong> geben die männliche und weibliche Form der erreichten Berufsbezeichnung an.</p><p>Das Feld <strong>DQR-Niveau</strong> enthält eine Zahl, die eines von acht Niveaus kenntlich macht. Hier ein Zitat von der Webseite des <a href="https://www.dqr.de" target="_blank" rel="noreferrer">deutschen Qualifikationsrahmen für lebenslanges Lernen</a>:</p><pre><code>Der DQR beschreibt acht Kompetenzniveaus, denen sich die Qualifikationen des deutschen Bildungssystems zuordnen lassen. Jedem Niveau ist ein kurzer Text vorangestellt, der die Anforderungsstruktur des jeweiligen Niveaus beschreibt. [...] Dabei geht es vor allem darum [...] mit Komplexität und unvorhersehbaren Veränderungen umzugehen, und mit welchem Grad von Selbständigkeit sie in einem beruflichen Tätigkeitsfeld oder in einem wissenschaftlichen Fach agieren können. (Abgerufen 18.06.2024)
</code></pre><p>Im Bereich <strong>Lernfelder</strong> ist ein frei editierbares Feld enthalten, das mit Informationen aus den Bildungsplänen ohne konkrete strukturelle Vorgabe zu befüllen ist. Die Bildungspläne sind auf den einschlägigen Webseiten, etwa der <a href="https://www.berufsbildung.nrw.de/" target="_blank" rel="noreferrer">QuaLis</a>, abzurufen.</p><p>Der eingetragene Text erscheint auf der Anlage beziehungsweise bei A3-Zeugnissen auf der Zeugnisrückseite. Gleichzeitig wird eine Fußnote mit Verweis auf die Anlage gesetzt.</p><p><a href="/bilder/unterricht-kataloge/kataloge-fachklassen-editor.png"><img src="`+d+'" alt="Der Editor zum Erstellen schöner Beschreibungen für die Lernfelder." loading="lazy"></a></p><p><em>Der Editor zum Erstellen schöner Beschreibungen für die Lernfelder.</em></p><p>Ein <code>Doppelklick</code> öffnet das Feld, dann kann mit einem Editor ein formatierter Text erstellt werden.</p><p>Sie können im Editor auch eine vorhandene Datei im <strong>Rich-Text-Format (.rtf)</strong> öffnen. Dieses Format speichert Text mit Formatierungen.</p><p>Der Editor bietet die üblichen Funktionen für einfache formatierte Texte.</p><p>Wählen Sie dazu <strong>Datei</strong> und laden Sie das gewünschte .rtf-Dokument.</p><p>Der grüne Pfeil im Screenshot weist auf die Funktion zum <code>Speichern &amp; schließen</code>.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Fachklassen_(Schulbezogene_Kataloge)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5649.</p>',35)])])}const b=n(g,[["render",h]]);export{m as __pageData,b as default};
